select c.country, round((100 * sum(case when t.merchant = 'Grab' then 1 else 0 end)) / count(*), 1) as pct_grab from transactions t inner join accounts a on t.account_id = a.id full outer join customers c on c.id = a.customer_id group by c.country having round((100 * sum(case when t.merchant = 'Grab' then 1 else 0 end)) / count(*), 1) > 47 order by pct_grab desc, country limit 10;
